#include<bits/stdc++.h>
using namespace std;
int v[20005];
int dp[20005];
int main(){
	int V,n;
	cin>>V>>n;
	for(int i=1;i<=n;i++){
		cin>>v[i];
	}
	for(int i=1;i<=V;i++){
		for(int j=V;j>=v[i];j--){
			dp[j]=max(dp[j],dp[j-v[i]]+v[i]);
		}
	}
	cout<<V-dp[V];
	return 0;
}

