#include<bits/stdc++.h>
#define int long long
using namespace std;
long long n, m, s, a[5505], dp[5505][5505], q[5505], pos[5505];
signed main(){
	cin >> n >> m >> s;
	for (int i = 1; i <= n; i++){
		cin >> a[i];
	}
	for (int i = 0; i <= n; i++)
		for (int j = 0; j <= m; ++j)
			dp[i][j] =-0x3f3f3f3f;
	dp[0][0] = 0;
	for (int i = 1; i <= n; i++){
		int l = 1, r = 1;
		q[l] = dp[i - 1][m];
		pos[l] = m;
		for (int j = m; j; j--){
			while (pos[l] > j + s - 1 && l <= r)
				l++;
			while (q[r] < dp[i - 1][j - 1] && l <= r)
				r--;
			pos[++r] = j - 1;
			q[r] = dp[i - 1][j - 1];
			dp[i][j] = q[l] + j * a[i];
		}
	}
	long long ans =-0x3f3f3f3f;
	for (int i = 0; i <= m; i++)ans = max(ans, dp[n][i]);
	cout << ans;
	return 0;
}

